package main
import("encoding/json";"log";"net/http";"os";v "github.com/MohammadSyed18/Volunteerops")
func main(){c:=v.New();mux:=http.NewServeMux();mux.HandleFunc("POST /volunteers",func(w http.ResponseWriter,r *http.Request){var x v.Volunteer;if json.NewDecoder(r.Body).Decode(&x)!=nil||c.AddVolunteer(x)!=nil{http.Error(w,"invalid volunteer",400);return};w.WriteHeader(201)});mux.HandleFunc("POST /shifts",func(w http.ResponseWriter,r *http.Request){var x v.Shift;if json.NewDecoder(r.Body).Decode(&x)!=nil||c.AddShift(x)!=nil{http.Error(w,"invalid shift",400);return};w.WriteHeader(201)});mux.HandleFunc("POST /request",func(w http.ResponseWriter,r *http.Request){var x struct{Volunteer,Shift string};if json.NewDecoder(r.Body).Decode(&x)!=nil{http.Error(w,"bad request",400);return};state,err:=c.Request(x.Volunteer,x.Shift);if err!=nil{http.Error(w,err.Error(),409);return};json.NewEncoder(w).Encode(map[string]string{"status":state})});addr:=os.Getenv("ADDR");if addr==""{addr=":8080"};log.Fatal(http.ListenAndServe(addr,mux))}
